package com.quincaisoft.sync.infrastructure;import jakarta.persistence.*;import java.util.*;import java.time.*;import java.io.Serializable;
@Entity @Table(name="sync_device") @IdClass(SyncDevice.Key.class) public class SyncDevice{public static record Key(UUID tenantId,UUID companyId,UUID id)implements Serializable{} public SyncDevice(){}
 @Id @Column(name="tenant_id") public UUID tenantId;@Id @Column(name="company_id") public UUID companyId;@Id public UUID id;@Column(name="branch_id")public UUID branchId; @Column(name="actor_id")public UUID actorId;public UUID epoch;public String name,status,challenge;@Column(name="public_key_pem")public String publicKeyPem;public String fingerprint;@Column(name="expires_at")public Instant expiresAt;public long version;@Column(name="approved_by")public UUID approvedBy;@Column(name="approval_reason")public String approvalReason;}
